import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  const dateResult = validateDate(issueDate);
  if (!dateResult.ok) return dateResult;

  if (!lines || !Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  const tierDiscount = TIER_DISCOUNTS[customerResult.value.tier];

  const enrichedLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) return discountValidation;

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;

    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

function validateDate(dateStr) {
  const dateRegex = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = dateRegex.exec(String(dateStr || ''));

  if (!match) return fail('DATE_INVALID');

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  if (!isValidDate(year, month, day)) {
    return fail('DATE_INVALID');
  }

  return ok(true);
}

function isValidDate(year, month, day) {
  if (month < 1 || month > 12) return false;
  if (day < 1) return false;

  const daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  if (month === 2 && ((year % 4 === 0 && year % 100 !== 0) || year % 400 === 0)) {
    return day <= 29;
  }

  return day <= daysInMonth[month - 1];
}

/**
 * Calculate the total for a single line (qty × unitPrice).
 * @param {{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} Discount in cents
 */
export function lineDiscount(line) {
  if (!line.discountPercent || line.discountPercent === 0) {
    return 0;
  }
  const total = lineTotal(line);
  return roundCents(total * line.discountPercent / 100);
}

/**
 * Calculate VAT for a single line (computed on the amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number} VAT in cents
 */
export function lineVAT(line) {
  if (!line.vatRate || line.vatRate === 0) {
    return 0;
  }
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = total - discount;
  return roundCents(amountAfterDiscount * line.vatRate / 100);
}

/**
 * Calculate subtotal, discount, VAT, and total for an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }} Amounts in cents
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  let vat = 0;

  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
    discount += lineDiscount(line);
    vat += lineVAT(line);
  }

  const total = Math.max(0, subtotal - discount + vat);

  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    vat: Math.max(0, vat),
    total,
  };
}

/**
 * Add a line item to a draft invoice. If the SKU already exists, increase its qty.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  const discountValidation = validateDiscount(discountPercent);
  if (!discountValidation.ok) return discountValidation;

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const tierDiscount = TIER_DISCOUNTS[customerResult.value.tier];
  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    const lineDiscountPercent = discountPercent !== undefined ? discountPercent : tierDiscount;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: lineDiscountPercent,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'draft',
    lines: newLines,
  });
}

/**
 * Remove a line item from a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'draft',
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array, number?: string }} invoice
 * @param {string[]} existingNumbers - Previously used invoice numbers
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'issued', lines: Array, number: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const numberResult = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  if (!numberResult.ok) return numberResult;

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    number: numberResult.value,
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

function validateDiscount(discountPercent) {
  if (discountPercent === undefined || discountPercent === null) {
    return ok(true);
  }

  if (typeof discountPercent !== 'number' || Number.isNaN(discountPercent) || discountPercent < 0 || discountPercent > 100) {
    return fail('DISCOUNT_INVALID');
  }

  return ok(true);
}

